-- Seed demo movimientos para probar conciliacion 20260903
-- Rango 2026-09-03, 50 demo: 47 conciliados, 1 dif monto, 2 no encontrados, 2 solo plataforma
-- Ejecutar en SQL Editor de Supabase (requiere cliente existente o crear uno dummy)
do $$
declare v_cliente_id uuid; v_est smallint; begin
  select id into v_cliente_id from clientes limit 1;
  if v_cliente_id is null then raise exception 'No hay clientes, crea uno'; end if;
  select id into v_est from estados_movimiento where codigo='APROBADO' limit 1;
end $$;
